-- Schema der Datenbank bis 0.11.0 (vor dem Anfangsstand 0.12.0), für den Test der Übergangs-Migration (#266)
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "categories" ("id" varchar not null, "key" varchar not null, "abbreviation" varchar, "name" varchar not null, "label" varchar, "description" text, "url" varchar, "note" text, "color" varchar, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "duplicate_decisions" ("id" integer primary key autoincrement not null, "signature" varchar not null, "kind" varchar not null, "value" varchar not null, "term_ids" text not null, "decided_by" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("decided_by") references "users"("id") on delete set null);
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "import_batches" ("id" integer primary key autoincrement not null, "user_id" varchar, "user_label" varchar, "file_name" varchar not null, "format_version" integer not null, "rows" integer not null, "created_count" integer not null, "updated_count" integer not null, "error_count" integer not null, "legacy_count" integer not null, "errors" text, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "organization_invitations" ("id" integer primary key autoincrement not null, "organization_id" varchar not null, "email" varchar not null, "invited_by" varchar, "expires_at" datetime not null, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("invited_by") references "users"("id") on delete set null);
CREATE TABLE "organization_members" ("id" integer primary key autoincrement not null, "organization_id" varchar not null, "user_id" varchar not null, "role" varchar not null default 'member', "status" varchar not null default 'active', "granted_role" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "organization_term_overrides" ("id" varchar not null, "organization_id" varchar not null, "term_id" varchar not null, "abbreviation_override" varchar, "name_override" varchar, "short_description_override" varchar, "description_override" text, "aliases_override" text, "updated_by" varchar, "created_at" datetime, "updated_at" datetime, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("term_id") references "terms"("id") on delete cascade, foreign key("updated_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "organizations" ("id" varchar not null, "name" varchar not null, "created_by" varchar, "created_at" datetime, "updated_at" datetime, foreign key("created_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "proposal_events" ("id" integer primary key autoincrement not null, "proposal_id" integer not null, "type" varchar not null, "actor_id" varchar, "actor_label" varchar, "by_author" tinyint(1) not null default '0', "message" text, "details" text, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("proposal_id") references "proposals"("id") on delete cascade);
CREATE TABLE "proposals" ("id" integer primary key autoincrement not null, "kind" varchar not null, "term_id" varchar, "base_revision" integer, "changes" text not null, "reason" text, "status" varchar not null default ('eingereicht'), "user_id" varchar, "service_account_id" varchar, "author_label" varchar not null, "result_term_id" varchar, "result_revision" integer, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, "organization_id" varchar, foreign key("result_term_id") references "terms"("id") on delete set null on update no action, foreign key("service_account_id") references "service_accounts"("id") on delete set null on update no action, foreign key("user_id") references "users"("id") on delete set null on update no action, foreign key("term_id") references "terms"("id") on delete set null on update no action, foreign key("organization_id") references "organizations"("id") on delete set null);
CREATE TABLE "publication_releases" ("id" integer primary key autoincrement not null, "term_id" varchar, "action" varchar not null, "checksum" varchar not null, "term_count" integer not null, "published_by" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("published_by") references "users"("id") on delete set null);
CREATE TABLE "role_permissions" ("role_id" varchar not null, "permission" varchar not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "permission"));
CREATE TABLE "roles" ("id" varchar not null, "key" varchar not null, "name" varchar not null, "description" varchar, "is_system" tinyint(1) not null default '0', "sort_order" integer not null default '100', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "service_account_audit" ("id" integer primary key autoincrement not null, "service_account_id" varchar, "token_id" varchar, "actor_id" varchar, "actor_label" varchar, "action" varchar not null, "details" text, "result" varchar not null default 'ok', "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "service_account_tokens" ("id" varchar not null, "service_account_id" varchar not null, "name" varchar not null, "token_hash" varchar not null, "prefix" varchar not null, "expires_at" datetime not null, "last_used_at" datetime, "revoked_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("service_account_id") references "service_accounts"("id") on delete cascade, primary key ("id"));
CREATE TABLE "service_accounts" ("id" varchar not null, "name" varchar not null, "purpose" varchar not null, "responsible_user_id" varchar, "status" varchar not null default ('active'), "scopes" text not null, "created_at" datetime, "updated_at" datetime, "organization_id" varchar, foreign key("responsible_user_id") references "users"("id") on delete set null on update no action, foreign key("organization_id") references "organizations"("id") on delete cascade, primary key ("id"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" varchar, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "settings" ("key" varchar not null, "value" text not null, "updated_by" varchar, "updated_at" datetime, primary key ("key"));
CREATE TABLE "sources" ("id" varchar not null, "key" varchar not null, "abbreviation" varchar, "name" varchar not null, "label" varchar, "description" text, "url" varchar, "note" text, "color" varchar, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "term_aliases" ("id" integer primary key autoincrement not null, "term_id" varchar not null, "alias" varchar not null, "alias_type" varchar not null, "language" varchar not null default 'de', foreign key("term_id") references "terms"("id") on delete cascade);
CREATE TABLE "term_categories" ("term_id" varchar not null, "category_id" varchar not null, foreign key("term_id") references "terms"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete restrict, primary key ("term_id", "category_id"));
CREATE TABLE "term_legacy_values" ("id" integer primary key autoincrement not null, "term_id" varchar not null, "field" varchar not null, "value" varchar not null, "origin" varchar not null, "resolution" varchar, "resolved_by" varchar, "resolved_at" datetime, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("term_id") references "terms"("id") on delete cascade, foreign key("resolved_by") references "users"("id") on delete set null);
CREATE TABLE "term_publication_events" ("id" integer primary key autoincrement not null, "term_id" varchar not null, "action" varchar not null, "revision" integer, "release_id" integer, "created_at" datetime not null default CURRENT_TIMESTAMP, "merged_into" varchar, "actor_type" varchar, "actor_label" varchar, "actor_id" varchar, foreign key("release_id") references "publication_releases"("id") on delete set null);
CREATE TABLE "term_revisions" ("id" varchar not null, "term_id" varchar not null, "revision" integer not null, "change_type" varchar not null, "snapshot" text not null, "author_id" varchar, "author_label" varchar, "approved_by" varchar, "published_at" datetime, "created_at" datetime not null default CURRENT_TIMESTAMP, "change_set" text, "actor_type" varchar, "context" text, foreign key("term_id") references "terms"("id") on delete cascade, foreign key("author_id") references "users"("id") on delete set null, foreign key("approved_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "term_sources" ("term_id" varchar not null, "source_id" varchar not null, "url" varchar, "retrieved_at" date, "note" varchar, "evidence" varchar, foreign key("term_id") references "terms"("id") on delete cascade, foreign key("source_id") references "sources"("id") on delete restrict, primary key ("term_id", "source_id"));
CREATE TABLE "term_user_overrides" ("id" varchar not null, "term_id" varchar not null, "user_id" varchar not null, "abbreviation_override" varchar, "name_override" varchar, "short_description_override" varchar, "description_override" text, "aliases_override" text, "created_at" datetime, "updated_at" datetime, "approved_organization_id" varchar, "approved_by" varchar, "approved_at" datetime, foreign key("user_id") references "users"("id") on delete cascade on update no action, foreign key("term_id") references "terms"("id") on delete cascade on update no action, foreign key("approved_organization_id") references "organizations"("id") on delete set null, foreign key("approved_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "terms" ("id" varchar not null, "slug" varchar not null, "official_abbreviation" varchar, "official_name" varchar, "short_description" varchar, "description" text, "note" text, "url" varchar, "search_terms" text, "lifecycle_status" varchar not null default 'aktuell', "is_active" tinyint(1) not null default '1', "valid_from" date, "valid_until" date, "revision" integer not null default '0', "published_revision_id" varchar, "created_at" datetime, "updated_at" datetime, "merged_into_id" varchar, "merged_at" datetime, "code" varchar, primary key ("id"));
CREATE TABLE "user_audit" ("id" integer primary key autoincrement not null, "actor_id" varchar, "actor_label" varchar, "target_user_id" varchar, "target_role_id" varchar, "action" varchar not null, "old" text, "new" text, "result" varchar not null default 'ok', "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "user_identities" ("id" integer primary key autoincrement not null, "user_id" varchar not null, "provider" varchar not null, "issuer" varchar not null, "subject" varchar not null, "tenant_id" varchar, "object_id" varchar, "last_used_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "user_roles" ("user_id" varchar not null, "role_id" varchar not null, foreign key("user_id") references "users"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("user_id", "role_id"));
CREATE TABLE "users" ("id" varchar not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "two_factor_last_step" integer, "status" varchar not null default 'active', "blocked_at" datetime, "first_name" varchar not null default '', "last_name" varchar not null default '', "community_name" varchar, "function" varchar, "institution_type" varchar, "institution_name" varchar, "last_login_on" date, "privacy_notice_version" varchar, "privacy_notice_acknowledged_at" datetime, "inactivity_notice_sent_at" datetime, "password_set" tinyint(1) not null default '1', "news_opt_in" tinyint(1) not null default '0', "news_answered_at" datetime, primary key ("id"));
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE UNIQUE INDEX "categories_key_unique" on "categories" ("key");
CREATE UNIQUE INDEX "duplicate_decisions_signature_unique" on "duplicate_decisions" ("signature");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "import_batches_created_at_index" on "import_batches" ("created_at");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "organization_invitations_email_index" on "organization_invitations" ("email");
CREATE UNIQUE INDEX "organization_invitations_organization_id_email_unique" on "organization_invitations" ("organization_id", "email");
CREATE INDEX "organization_members_organization_id_role_index" on "organization_members" ("organization_id", "role");
CREATE UNIQUE INDEX "organization_members_user_id_unique" on "organization_members" ("user_id");
CREATE UNIQUE INDEX "organization_term_overrides_organization_id_term_id_unique" on "organization_term_overrides" ("organization_id", "term_id");
CREATE UNIQUE INDEX "organizations_name_unique" on "organizations" ("name");
CREATE INDEX "proposals_resolved_at_index" on "proposals" ("resolved_at");
CREATE INDEX "proposals_status_index" on "proposals" ("status");
CREATE UNIQUE INDEX "roles_key_unique" on "roles" ("key");
CREATE INDEX "service_account_audit_actor_id_index" on "service_account_audit" ("actor_id");
CREATE INDEX "service_account_audit_service_account_id_index" on "service_account_audit" ("service_account_id");
CREATE UNIQUE INDEX "service_account_tokens_token_hash_unique" on "service_account_tokens" ("token_hash");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE UNIQUE INDEX "sources_key_unique" on "sources" ("key");
CREATE INDEX "term_aliases_alias_index" on "term_aliases" ("alias");
CREATE UNIQUE INDEX "term_legacy_values_term_id_field_value_unique" on "term_legacy_values" ("term_id", "field", "value");
CREATE INDEX "term_publication_events_term_id_index" on "term_publication_events" ("term_id");
CREATE UNIQUE INDEX "term_revisions_term_id_revision_unique" on "term_revisions" ("term_id", "revision");
CREATE UNIQUE INDEX "term_user_overrides_term_id_user_id_unique" on "term_user_overrides" ("term_id", "user_id");
CREATE INDEX "term_user_overrides_user_id_index" on "term_user_overrides" ("user_id");
CREATE UNIQUE INDEX "terms_code_unique" on "terms" ("code");
CREATE INDEX "terms_merged_into_id_index" on "terms" ("merged_into_id");
CREATE INDEX "terms_official_abbreviation_index" on "terms" ("official_abbreviation");
CREATE INDEX "terms_published_revision_id_index" on "terms" ("published_revision_id");
CREATE UNIQUE INDEX "terms_slug_unique" on "terms" ("slug");
CREATE INDEX "user_audit_actor_id_index" on "user_audit" ("actor_id");
CREATE INDEX "user_audit_target_role_id_index" on "user_audit" ("target_role_id");
CREATE INDEX "user_audit_target_user_id_index" on "user_audit" ("target_user_id");
CREATE UNIQUE INDEX "user_identities_provider_issuer_subject_unique" on "user_identities" ("provider", "issuer", "subject");
CREATE INDEX "user_roles_role_id_index" on "user_roles" ("role_id");
CREATE UNIQUE INDEX "users_community_name_unique" on "users" ("community_name");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "users_status_index" on "users" ("status");
